#!/usr/bin/env node
// Validates instances.yaml and writes sidebars/<id>.ts for every instance that has no curated one.
//
// Runs as the `prestart` and `prebuild` scripts: Docusaurus needs each instance's sidebarPath to
// exist before it loads the config, and doesn't create it.
//
// A generated sidebar starts with GENERATED_MARKER. A file without the marker is curated: it's
// committed and this script never touches it. The generated files are listed in
// sidebars/.gitignore (which ignores itself), so they never show up in `git status`.
import fs from 'node:fs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
import {loadInstances, InstancesError} from './instances.mjs';

const siteDir = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const sidebarsDir = path.join(siteDir, 'sidebars');

const GENERATED_MARKER = '// Generated by scripts/gen-sidebars.mjs.';

const generated = `${GENERATED_MARKER} Commit a file without this line to curate the sidebar.
export default { main: [{ type: 'autogenerated', dirName: '.' }] };
`;

function isGenerated(file) {
  return fs.readFileSync(file, 'utf8').startsWith(GENERATED_MARKER);
}

function main() {
  const {manifest, empty} = loadInstances(siteDir);
  fs.mkdirSync(sidebarsDir, {recursive: true});

  const ids = new Set(manifest.instances.map((i) => i.id));
  const written = [];
  const curated = [];
  for (const id of ids) {
    const file = path.join(sidebarsDir, `${id}.ts`);
    if (fs.existsSync(file) && !isGenerated(file)) {
      curated.push(id);
      continue;
    }
    fs.writeFileSync(file, generated);
    written.push(id);
  }

  // Drop generated sidebars of instances that left the manifest.
  for (const name of fs.readdirSync(sidebarsDir)) {
    const file = path.join(sidebarsDir, name);
    if (name.endsWith('.ts') && !ids.has(name.slice(0, -3)) && isGenerated(file)) {
      fs.rmSync(file);
    }
  }

  fs.writeFileSync(
    path.join(sidebarsDir, '.gitignore'),
    [
      '# Written by scripts/gen-sidebars.mjs: the sidebars it generated, and this file.',
      '.gitignore',
      ...written.map((id) => `${id}.ts`),
      '',
    ].join('\n'),
  );

  console.log(
    `gen-sidebars: ${manifest.instances.length} instances; generated ${written.length}, curated ${curated.length}.`,
  );
  if (empty.length > 0) {
    console.log(`gen-sidebars: no pages yet, not built: ${empty.map((i) => i.id).join(', ')}.`);
  }
}

try {
  main();
} catch (err) {
  if (err instanceof InstancesError || err.name === 'YAMLException') {
    console.error(`gen-sidebars: ${err.message}`);
    process.exit(1);
  }
  throw err;
}
